window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e66c3fa4385b438f"]={"versions": [{"id": "FIG-e66c3fa4385b438f", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Feature-Modell / Feature-Dekompositionsdiagramm (FODA-Notation / Feature-Oriented Domain Analysis) gemäß AUTOSAR Foundation (<code>AUTOSAR_FO_TR_Features</code>).</li>\n<li><strong>Funktionale Einordnung:</strong> Dekomposition des Foundation-Features <code>FO_TR_FEAT_00096</code> (<em>Standardized_Application_Interface</em>). Es verankert plattformübergreifend (Classic Platform und Adaptive Platform) die herstellerunabhängige Standardisierung von Applikationsschnittstellen auf VFB-Ebene (Virtual Function Bus), um die Interoperabilität und Austauschbarkeit von Software-Komponenten (SWCs) über Domänengrenzen hinweg sicherzustellen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Knoten (Feature-Entitäten):</strong></li>\n<li><strong>Wurzel-Feature:</strong></li>\n<li><code>FO_TR_FEAT_00096</code> (<code>Standardized_Application_Interface</code>): Übergeordnetes Feature zur Bereitstellung standardisierter Schnittstellenkataloge, Schnittstellensemantiken und Datendefinitionen für AUTOSAR-Applikationen.</li>\n<li><strong>Abgeleitete Sub-Features:</strong></li>\n<li><code>FO_TR_FEAT_00110</code> (<code>Physical_Dimensions_And_Units</code>): Spezifikation einheitlicher physikalischer Größen, SI-Einheiten, Umrechnungsfaktoren und Skalierungsregeln für Port-Variablen und Argumente.</li>\n<li><code>FO_TR_FEAT_00097</code> (<code>Vehicle_Domain_Interfaces</code>): Domänenspezifische Schnittstellendefinitionen für Fahrzeugfunktionsbereiche (z. B. Powertrain, Chassis, Body, ADAS).</li>\n<li><code>FO_TR_FEAT_00107</code> (<code>AIF_Method</code>): Definition der Methodik und Modellierungsregeln des <em>Application Interface Frameworks</em> (AIF) zur konsistenten Definition, Pflege und Erweiterung von Applikations-Interfaces.</li>\n<li><strong>Relationen & Semantik:</strong></li>\n<li>Gerichtete hierarchische Verfeinerung von oben nach unten.</li>\n<li>Die Kanten terminieren an den Zielknoten mit einem ungefüllten Kreis (<em>empty circle</em>): Kennzeichnung aller drei Sub-Features als <strong>optional</strong> bezüglich des übergeordneten Features <code>FO_TR_FEAT_00096</code> (keine zwingende Kookkurenz, modulare Implementierbarkeit).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Nicht zutreffend:</strong> Rein statische Dekomposition von Architekturanforderungen und Metamodell-Features.</li>\n<li>Das Diagramm enthält keine Laufzeitsemantik, keine Zustandsübergänge, keinen Kontroll-/Datenfluss und keine Callbacks.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>SWC- & Interface-Modellierung:</strong> Applikationsentwickler, die standardisierte SWCs für Classic (RTE) oder Adaptive (ara::com) Plattformen implementieren, müssen Port-Interfaces (Sender-Receiver, Client-Server) konform zu den in <code>FO_TR_FEAT_00097</code> definierten Blaupausen und Naming Conventions strukturieren.</li>\n<li><strong>Typkonsistenz & Einheiten:</strong> <code>FO_TR_FEAT_00110</code> bindet die ARXML-Datentypdefinitionen (<code>ApplicationDataType</code>, <code>ImplementationDataType</code>) an standardisierte <code>CompuMethod</code>-, <code>Unit</code>- und <code>PhysicalDimension</code>-Elemente. Entwickler müssen Rundungsfehler, Wertebereiche und Skalierungsfaktoren strikt nach diesen Spezifikationen auslegen, um semantische Fehlinterpretationen zwischen Sender- und Receiver-Komponenten auszuschließen.</li>\n<li><strong>Konfigurationsumfang:</strong> Da die Sub-Features optional deklariert sind, können OEMs und Zulieferer den Konformitätsumfang modular zuschneiden (z. B. Nutzung von <code>Physical_Dimensions_And_Units</code> ohne vollständige Übernahme des herstellerspezifischen <code>Vehicle_Domain_Interfaces</code>-Katalogs).</li>\n</ul>"}, {"id": "FIG-1b54d70aba514efd", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Feature-Modell / Feature-Dekompositionsdiagramm (FODA-Notation / Feature-Oriented Domain Analysis) gemäß AUTOSAR Foundation (<code>AUTOSAR_FO_TR_Features</code>).</li>\n<li><strong>Funktionale Einordnung:</strong> Dekomposition des Foundation-Features <code>FO_TR_FEAT_00096</code> (<em>Standardized_Application_Interface</em>). Es verankert plattformübergreifend (Classic Platform und Adaptive Platform) die herstellerunabhängige Standardisierung von Applikationsschnittstellen auf VFB-Ebene (Virtual Function Bus), um die Interoperabilität und Austauschbarkeit von Software-Komponenten (SWCs) über Domänengrenzen hinweg sicherzustellen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Knoten (Feature-Entitäten):</strong></li>\n<li><strong>Wurzel-Feature:</strong></li>\n<li><code>FO_TR_FEAT_00096</code> (<code>Standardized_Application_Interface</code>): Übergeordnetes Feature zur Bereitstellung standardisierter Schnittstellenkataloge, Schnittstellensemantiken und Datendefinitionen für AUTOSAR-Applikationen.</li>\n<li><strong>Abgeleitete Sub-Features:</strong></li>\n<li><code>FO_TR_FEAT_00110</code> (<code>Physical_Dimensions_And_Units</code>): Spezifikation einheitlicher physikalischer Größen, SI-Einheiten, Umrechnungsfaktoren und Skalierungsregeln für Port-Variablen und Argumente.</li>\n<li><code>FO_TR_FEAT_00097</code> (<code>Vehicle_Domain_Interfaces</code>): Domänenspezifische Schnittstellendefinitionen für Fahrzeugfunktionsbereiche (z. B. Powertrain, Chassis, Body, ADAS).</li>\n<li><code>FO_TR_FEAT_00107</code> (<code>AIF_Method</code>): Definition der Methodik und Modellierungsregeln des <em>Application Interface Frameworks</em> (AIF) zur konsistenten Definition, Pflege und Erweiterung von Applikations-Interfaces.</li>\n<li><strong>Relationen & Semantik:</strong></li>\n<li>Gerichtete hierarchische Verfeinerung von oben nach unten.</li>\n<li>Die Kanten terminieren an den Zielknoten mit einem ungefüllten Kreis (<em>empty circle</em>): Kennzeichnung aller drei Sub-Features als <strong>optional</strong> bezüglich des übergeordneten Features <code>FO_TR_FEAT_00096</code> (keine zwingende Kookkurenz, modulare Implementierbarkeit).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Nicht zutreffend:</strong> Rein statische Dekomposition von Architekturanforderungen und Metamodell-Features.</li>\n<li>Das Diagramm enthält keine Laufzeitsemantik, keine Zustandsübergänge, keinen Kontroll-/Datenfluss und keine Callbacks.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>SWC- & Interface-Modellierung:</strong> Applikationsentwickler, die standardisierte SWCs für Classic (RTE) oder Adaptive (ara::com) Plattformen implementieren, müssen Port-Interfaces (Sender-Receiver, Client-Server) konform zu den in <code>FO_TR_FEAT_00097</code> definierten Blaupausen und Naming Conventions strukturieren.</li>\n<li><strong>Typkonsistenz & Einheiten:</strong> <code>FO_TR_FEAT_00110</code> bindet die ARXML-Datentypdefinitionen (<code>ApplicationDataType</code>, <code>ImplementationDataType</code>) an standardisierte <code>CompuMethod</code>-, <code>Unit</code>- und <code>PhysicalDimension</code>-Elemente. Entwickler müssen Rundungsfehler, Wertebereiche und Skalierungsfaktoren strikt nach diesen Spezifikationen auslegen, um semantische Fehlinterpretationen zwischen Sender- und Receiver-Komponenten auszuschließen.</li>\n<li><strong>Konfigurationsumfang:</strong> Da die Sub-Features optional deklariert sind, können OEMs und Zulieferer den Konformitätsumfang modular zuschneiden (z. B. Nutzung von <code>Physical_Dimensions_And_Units</code> ohne vollständige Übernahme des herstellerspezifischen <code>Vehicle_Domain_Interfaces</code>-Katalogs).</li>\n</ul>"}], "trans": [{"from": "FIG-e66c3fa4385b438f", "to": "FIG-1b54d70aba514efd", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
